  compilerVersion: string;
  policyHash: string;
  rolloutDefaults?: {
    mode: AuthorizationRolloutMode;
    canaryPercent: number;
    mismatchThreshold?: number;
    fallbackRateThreshold?: number;
  };
}

export interface AuthorizationActor {
  accountId: string;
  tenantId?: string | null;
